pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(from != address(0));

        // Deploy a helper that records calls to detect whether external calls are actually made.
        CallRecorder recorder = new CallRecorder();
        address caddress = address(recorder);

        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            // Reference always calls into caddress for each _tos, so the recorder must have received all calls.
            assertTrue(recorder.callCount() == _tos.length);
        } catch {
            // If the call reverts, this input is not in the admissible domain of "completes without reverting".
            // We skip assertion.
        }
    }
}

contract CallRecorder {
    uint public callCount;
    function transferFrom(address, address, uint256) external {
        callCount++;
    }
}

