pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // Deploy an adversarial callee that reverts on any incoming call
        Reverter reverter = new Reverter();
        bool ok;
        try c.transfer(from, address(reverter), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        // The reference must revert (external call to Reverter reverts),
        // the mutant does not call and will not revert, so ok is true.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

