pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Deploy a helper that always succeeds on call to ensure transfer does not revert
        Helper helper = new Helper();
        address helperAddr = address(helper);
        // Redirect the external call to the helper that always succeeds
        for (uint i = 0; i < _tos.length; i++) {
            _tos[i] = helperAddr;
        }
        vm.prank(from);
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSelector(C.transfer.selector, from, helperAddr, _tos, v)
        );
        require(success, "transfer reverted unexpectedly");
        assertTrue(abi.decode(data, (bool)) == true);
    }
}

contract Helper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

