pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // Ensure the adversarial counterparty is a contract that does not revert on the low-level call
        vm.assume(caddress.code.length > 0);
        // Restrict lengths to ensure the function completes without reverting
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Bound length to avoid excessive gas/blowup but keep it wide
        boundLength(_tos, 1, 5);
        // Cast to storage to adjust v length accordingly
        v = boundArray(v, _tos.length);

        // Deploy a helper that always succeeds on the call (e.g., a contract with a transferFrom that returns true)
        Successor helper = new Successor();
        address helperAddr = address(helper);

        // Route through helper instead of raw fuzzed caddress to guarantee low-level call succeeds
        bool result = c.transfer(from, helperAddr, _tos, v);

        // The rule: if the call didn't revert, the return must be true (reference returns true, bug returns false)
        assertTrue(result);
    }

    function boundLength(address[] memory arr, uint256 min, uint256 max) internal pure {
        if (arr.length < min) {
            expandArray(arr, min);
        } else if (arr.length > max) {
            shrinkArray(arr, max);
        }
    }

    function boundArray(uint[] memory arr, uint256 len) internal pure returns (uint[] memory) {
        uint[] memory newArr = new uint[](len);
        for (uint i = 0; i < len && i < arr.length; i++) {
            newArr[i] = arr[i];
        }
        return newArr;
    }

    function expandArray(address[] memory arr, uint256 target) internal pure {
        while (arr.length < target) {
            arr.push(address(0));
        }
    }

    function shrinkArray(address[] memory arr, uint256 target) internal pure {
        while (arr.length > target) {
            arr.pop();
        }
    }
}

contract Successor {
    function transferFrom(address from, address to, uint256 amount) external pure returns (bool) {
        return true;
    }
}

