    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Use a helper that always succeeds for the low-level calls to ensure no revert
        Successor helper = new Successor();
        // Fuzzed caddress is replaced by the successful helper
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, address(helper), _tos, v));
        bool externalOk = ok;
        bool internalRet = abi.decode(ret, (bool));
